def calculate_atr_stop(entry_price, atr_value, multiplier=2.0, is_long=True):
    # GOOD: dynamically adapts stop distance based on market volatility
    if is_long:
        return entry_price - (atr_value * multiplier)
    return entry_price + (atr_value * multiplier)
